"use client";

import { useEffect, useRef } from "react";
import * as THREE from "three";

export default function ThreeScene({ settings }) {
  const ref = useRef(null);

  useEffect(() => {
    const container = ref.current;
    const renderer = new THREE.WebGLRenderer({ antialias: true });
    renderer.setSize(container.clientWidth, container.clientHeight);
    container.appendChild(renderer.domElement);

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(
      60,
      container.clientWidth / container.clientHeight,
      0.1,
      1000
    );

    const cubeGeometry = new THREE.BoxGeometry();
    const cubeMaterial = new THREE.MeshStandardMaterial({ color: 0x66ccff });
    const cube = new THREE.Mesh(cubeGeometry, cubeMaterial);
    cube.position.set(0, 0.5, 0);
    scene.add(cube);

    const planeGeometry = new THREE.PlaneGeometry(20, 20);
    const planeMaterial = new THREE.MeshStandardMaterial({ color: 0x444444 });
    const plane = new THREE.Mesh(planeGeometry, planeMaterial);
    plane.rotation.x = -Math.PI / 2;
    scene.add(plane);

    const light = new THREE.DirectionalLight(0xffffff, 1);
    light.position.set(10, 15, 10);
    scene.add(light);

    camera.position.set(5, 5, 5);
    camera.lookAt(cube.position);

    let yaw = Math.atan2(camera.position.x, camera.position.z);
    let pitch = Math.atan2(
      camera.position.y,
      Math.hypot(camera.position.x, camera.position.z)
    );

    const keys = {};
    const moveSpeed = 0.2;
    const lookSpeed = 0.003;
    let isMouseDown = false;
    let lastMouse = { x: 0, y: 0 };

    const onMouseDown = (e) => {
      isMouseDown = true;
      lastMouse.x = e.clientX;
      lastMouse.y = e.clientY;
    };
    const onMouseMove = (e) => {
      if (!isMouseDown) return;
      const dx = e.clientX - lastMouse.x;
      const dy = e.clientY - lastMouse.y;
      lastMouse.x = e.clientX;
      lastMouse.y = e.clientY;
      yaw -= dx * lookSpeed;
      pitch -= dy * lookSpeed;
      pitch = Math.max(
        -Math.PI / 2 + 0.01,
        Math.min(Math.PI / 2 - 0.01, pitch)
      );
    };
    const onMouseUp = () => (isMouseDown = false);

    const onKeyDown = (e) => (keys[e.key.toLowerCase()] = true);
    const onKeyUp = (e) => (keys[e.key.toLowerCase()] = false);

    window.addEventListener("mousedown", onMouseDown);
    window.addEventListener("mousemove", onMouseMove);
    window.addEventListener("mouseup", onMouseUp);
    window.addEventListener("keydown", onKeyDown);
    window.addEventListener("keyup", onKeyUp);

    const loop = () => {
      const forward = new THREE.Vector3(Math.sin(yaw), 0, Math.cos(yaw));
      const right = new THREE.Vector3(Math.cos(yaw), 0, -Math.sin(yaw));

      if (keys["w"]) camera.position.addScaledVector(forward, moveSpeed);
      if (keys["s"]) camera.position.addScaledVector(forward, -moveSpeed);
      if (keys["a"]) camera.position.addScaledVector(right, -moveSpeed);
      if (keys["d"]) camera.position.addScaledVector(right, moveSpeed);

      const target = new THREE.Vector3(
        camera.position.x + Math.sin(yaw) * Math.cos(pitch),
        camera.position.y + Math.sin(pitch),
        camera.position.z + Math.cos(yaw) * Math.cos(pitch)
      );
      camera.lookAt(target);

      cube.rotation.y += 0.01;
      renderer.render(scene, camera);
      requestAnimationFrame(loop);
    };
    loop();

    const handleResize = () => {
      renderer.setSize(container.clientWidth, container.clientHeight);
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
    };
    window.addEventListener("resize", handleResize);

    return () => {
      window.removeEventListener("resize", handleResize);
      window.removeEventListener("mousedown", onMouseDown);
      window.removeEventListener("mousemove", onMouseMove);
      window.removeEventListener("mouseup", onMouseUp);
      window.removeEventListener("keydown", onKeyDown);
      window.removeEventListener("keyup", onKeyUp);
      container.removeChild(renderer.domElement);
      renderer.dispose();
      cubeGeometry.dispose();
      cubeMaterial.dispose();
      planeGeometry.dispose();
      planeMaterial.dispose();
    };
  }, [settings]);

  return <div ref={ref} className="w-full h-full bg-black" />;
}
